function cancelGesture(type,d={}){const id=virtualKey(type,d),pressed=id&&pressedInputs.get(id);if(!pressed)return;pressedInputs.delete(id);const c=pressed.cancel;if(!c||c.lessonId!==activeLessonId)return;physicallyHeld.delete(c.key);if(c.mode==="action"&&actionCursor===c.actionCursor+1){actionCursor=c.actionCursor;actionSubCursor=c.actionSubCursor;}else if(c.mode==="subcue"&&actionCursor===c.actionCursor&&actionSubCursor===c.actionSubCursor+1)actionSubCursor=c.actionSubCursor;else return;refreshRecordedHolds();updateTeachingPanel();updateGestureHelp();notice("Cancelled press; the recorded cue remains active.");}
function bindPress(button,type,details){const input=state=>gesture(type,{...details,state});button.addEventListener("pointerdown",e=>{e.preventDefault();button.setPointerCapture(e.pointerId);input(1);});button.addEventListener("pointerup",()=>input(0));button.addEventListener("pointercancel",()=>cancelGesture(type,details));button.addEventListener("lostpointercapture",()=>cancelGesture(type,details));button.addEventListener("keydown",e=>{if(["Enter"," ","Space"].includes(e.key)){e.preventDefault();if(!e.repeat)input(1);}});button.addEventListener("keyup",e=>{if(["Enter"," ","Space"].includes(e.key))input(0);});}

