 for(const link of f.lesson_context_links||[]){const detail=node("section",undefined,$("details"),"lesson-context-link");detail.id="lesson-context-"+link.lesson_id;node("h3",link.label,detail);node("p",link.reason,detail);const a=node("a","Open full lesson: "+link.label,detail);a.href="#"+link.canonical_route;}
