 const relatedNames={"merge-modes":"Merge modes","channel-length":"Channel length","chord-strum":"Chord strum","fully-quantise-mask":"Fully quantise masks","arm-live-record":"Live recording","elektron-program-changes":"Elektron Program Changes","midi-controller-mapping":"MIDI Controller Mapping"};
